B.a5h=new A.aL(58735,"MaterialIcons",!1)
B.ao6=new A.bl([B.aT,"Une relation en suspens : regarde-la sous un autre angle.",B.aU,"Des projets bloqu\xe9s, \xe0 repenser plut\xf4t qu'\xe0 forcer.",B.aV,"Une pause impos\xe9e, qui cache une le\xe7on.",B.aW,"La paix vient de ce que tu acceptes de ne plus retenir."],t.C)
